create extension if not exists pgcrypto;
create table public.restaurants (id uuid primary key default gen_random_uuid(), name text not null default 'My Restaurant', currency text not null default 'INR', timezone text not null default 'Asia/Kolkata', created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, restaurant_id uuid not null references public.restaurants(id) on delete cascade, full_name text not null default '', role text not null default 'waiter' check (role in ('owner','manager','cashier','waiter','kitchen')), active boolean not null default true, created_at timestamptz not null default now());
create table public.restaurant_tables (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, table_number text not null, seats integer not null default 4 check (seats > 0), status text not null default 'available' check (status in ('available','occupied','reserved','bill_requested')), created_at timestamptz not null default now(), unique (restaurant_id, table_number));
create table public.menu_categories (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, name text not null, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), unique (restaurant_id, name));
create table public.menu_items (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, category_id uuid references public.menu_categories(id) on delete set null, name text not null, description text not null default '', price_paise integer not null check (price_paise >= 0), available boolean not null default true, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, table_id uuid not null references public.restaurant_tables(id), order_number bigint generated by default as identity, status text not null default 'open' check (status in ('open','sent','preparing','ready','bill_requested','paid','cancelled')), created_by uuid references public.profiles(id) on delete set null, notes text not null default '', opened_at timestamptz not null default now(), closed_at timestamptz, unique (restaurant_id, order_number));
create table public.order_items (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, menu_item_id uuid references public.menu_items(id) on delete set null, item_name text not null, unit_price_paise integer not null check (unit_price_paise >= 0), quantity integer not null default 1 check (quantity > 0), notes text not null default '', kitchen_status text not null default 'new' check (kitchen_status in ('new','queued','preparing','ready','served','cancelled')), created_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, order_id uuid not null references public.orders(id), amount_paise integer not null check (amount_paise > 0), method text not null check (method in ('cash','upi','card','other')), reference text not null default '', received_by uuid references public.profiles(id) on delete set null, paid_at timestamptz not null default now());
create index orders_restaurant_status_idx on public.orders(restaurant_id, status);
create index orders_table_status_idx on public.orders(table_id, status);
create index order_items_order_idx on public.order_items(order_id);
create index payments_order_idx on public.payments(order_id);
create or replace function public.is_restaurant_member(target_restaurant uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.restaurant_id = target_restaurant and p.active = true); $$;
create or replace function public.current_restaurant_role() returns text language sql stable security definer set search_path = '' as $$ select p.role from public.profiles p where p.id = (select auth.uid()) and p.active = true limit 1; $$;
alter table public.restaurants enable row level security;
alter table public.profiles enable row level security;
alter table public.restaurant_tables enable row level security;
alter table public.menu_categories enable row level security;
alter table public.menu_items enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.payments enable row level security;
create policy "restaurant members read restaurant" on public.restaurants for select to authenticated using (public.is_restaurant_member(id));
create policy "owners manage restaurant" on public.restaurants for update to authenticated using (public.is_restaurant_member(id) and public.current_restaurant_role() in ('owner','manager')) with check (public.is_restaurant_member(id) and public.current_restaurant_role() in ('owner','manager'));
create policy "members read profiles" on public.profiles for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "owners manage profiles" on public.profiles for all to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager'));
create policy "members read tables" on public.restaurant_tables for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "managers manage tables" on public.restaurant_tables for all to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier'));
create policy "members read categories" on public.menu_categories for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "managers manage categories" on public.menu_categories for all to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager'));
create policy "members read menu" on public.menu_items for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "managers manage menu" on public.menu_items for all to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager'));
create policy "members read orders" on public.orders for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "staff create orders" on public.orders for insert to authenticated with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter'));
create policy "staff update orders" on public.orders for update to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter','kitchen')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter','kitchen'));
create policy "members read order items" on public.order_items for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "staff add order items" on public.order_items for insert to authenticated with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter'));
create policy "staff update order items" on public.order_items for update to authenticated using (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter','kitchen')) with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier','waiter','kitchen'));
create policy "members read payments" on public.payments for select to authenticated using (public.is_restaurant_member(restaurant_id));
create policy "cashiers record payments" on public.payments for insert to authenticated with check (public.is_restaurant_member(restaurant_id) and public.current_restaurant_role() in ('owner','manager','cashier'));
alter publication supabase_realtime add table public.restaurant_tables;
alter publication supabase_realtime add table public.orders;
alter publication supabase_realtime add table public.order_items;
